const size_t kEmotionClipCount = 13;

const emotion_clip_t *emotion_find(const char *name)
{
    if (!name) return NULL;
    for (size_t i = 0; i < kEmotionClipCount; ++i) {
        if (strcmp(kEmotionClips[i].name, name) == 0) return &kEmotionClips[i];
    }
    return NULL;
}
